// Apprentissage supervisé : classification simplifiée (pseudo-code)
function trainClassifier(examples) {
  // examples = [{ features: [...], label: 'spam' | 'not_spam' }, ...]
  const model = initializeModel()

  for (const epoch of range(numEpochs)) {
    for (const example of examples) {
      const prediction = model.predict(example.features)
      const error = example.label - prediction
      model.adjustWeights(error)          // ajustement progressif des paramètres
    }
  }
  return model
}

function classify(model, newEmail) {
  const features = extractFeatures(newEmail)  // ex: fréquence de certains mots
  return model.predict(features)              // 'spam' ou 'not_spam'
}

// Un neurone artificiel simplifié
function neuron(inputs, weights, bias) {
  let sum = bias
  for (let i = 0; i < inputs.length; i++) {
    sum += inputs[i] * weights[i]      // combinaison pondérée des entrées
  }
  return activation(sum)               // non-linéarité (ex: ReLU, sigmoid)
}

function activation(x) {
  return Math.max(0, x)                // ReLU : simple mais très efficace en pratique
}

// Passage avant dans un réseau à plusieurs couches
function forwardPass(input, layers) {
  let activations = input
  for (const layer of layers) {
    activations = layer.map((neuron) => neuron(activations, neuron.weights, neuron.bias))
  }
  return activations                   // sortie finale du réseau
}

// Génération de texte par prédiction séquentielle (pseudo-code très simplifié)
function generateText(prompt, model, maxTokens) {
  let tokens = tokenize(prompt)

  for (let i = 0; i < maxTokens; i++) {
    const probabilities = model.predictNextToken(tokens)  // distribution sur tout le vocabulaire
    const nextToken = sampleFrom(probabilities, temperature)  // choix pondéré, pas toujours le plus probable
    tokens.push(nextToken)

    if (nextToken === END_TOKEN) break
  }

  return detokenize(tokens)
}
